original_code:
module mealy_door_lock (
    input  logic clk,
    input  logic rst_n,
    input  logic [1:0] code_input,
    input  logic enter_btn,
    output logic unlock,
    output logic error
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE,       // Waiting for first digit
        DIGIT1,     // First digit entered
        DIGIT2      // Second digit entered
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Combinational block: next state logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (enter_btn)
                    1'b1: next_state = DIGIT1;
                endcase
            end

            DIGIT1: begin
                case (enter_btn)
                    1'b1: next_state = DIGIT2;
                endcase
            end

            DIGIT2: begin
                case (enter_btn)
                    1'b1: next_state = IDLE;  // Reset after attempt
                endcase
            end
        endcase
    end

    // Combinational block: Mealy outputs
    always_comb begin
        unlock = 1'b0;
        error = 1'b0;

        case (current_state)
            DIGIT2: begin
                case (enter_btn)
                    1'b1: begin
                        // Correct code is 2'b10 (binary 2)
                        case (code_input == 2'b10)
                            1'b1: unlock = 1'b1;   // Mealy: unlock on correct code
                            1'b0: error = 1'b1;    // Mealy: error on wrong code
                        endcase
                    end
                endcase
            end

            default: begin
                unlock = 1'b0;
                error = 1'b0;
            end
        endcase
    end

endmodule

