module axi2apb_bridge (
    input  logic        clk,
    input  logic        rst_n,

    // AXI4-Lite Slave Interface
    input  logic [31:0] s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [31:0] s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready,

    // APB Master Interface
    output logic [31:0] m_apb_paddr,
    output logic        m_apb_psel,
    output logic        m_apb_penable,
    output logic        m_apb_pwrite,
    output logic [31:0] m_apb_pwdata,
    input  logic [31:0] m_apb_prdata,
    input  logic        m_apb_pready,
    input  logic        m_apb_pslverr
);

	// State encoding
    typedef enum logic [1:0] {
        IDLE,
        SETUP,
        ACCESS,
        RESPONSE
    } state_t;

    // Signal declarations
    state_t current_state, next_state;
    logic [31:0] addr_reg;
    logic write_reg;
    logic is_write, is_read;
    logic aw_hsk, w_hsk, ar_hsk;

    // Block 1: State Machine Sequential Logic
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Address and Control Register
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                addr_reg <= 32'b0;
                write_reg <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case ({s_axi_awvalid, s_axi_arvalid})
                            2'b10, 2'b11: begin
                                addr_reg <= s_axi_awaddr;
                                write_reg <= 1'b1;
                            end
                            2'b01: begin
                                addr_reg <= s_axi_araddr;
                                write_reg <= 1'b0;
                            end
                            default: begin
                                addr_reg <= addr_reg;
                                write_reg <= write_reg;
                            end
                        endcase
                    end
                    default: begin
                        addr_reg <= addr_reg;
                        write_reg <= write_reg;
                    end
                endcase
            end
        endcase
    end

    // Block 3: Combinational Logic (All case statements, no assign)
    always_comb begin
        // Default values
        next_state = current_state;
        is_write = 1'b0;
        is_read = 1'b0;
        aw_hsk = 1'b0;
        w_hsk = 1'b0;
        ar_hsk = 1'b0;

        // Calculate handshake signals using case
        case ({s_axi_awvalid, s_axi_awready})
            2'b11: aw_hsk = 1'b1;
            default: aw_hsk = 1'b0;
        endcase

        case ({s_axi_wvalid, s_axi_wready})
            2'b11: w_hsk = 1'b1;
            default: w_hsk = 1'b0;
        endcase

        case ({s_axi_arvalid, s_axi_arready})
            2'b11: ar_hsk = 1'b1;
            default: ar_hsk = 1'b0;
        endcase

        // Calculate is_write and is_read
        case ({s_axi_awvalid, current_state == ACCESS})
            2'b10, 2'b11, 2'b01: is_write = 1'b1;
            default: is_write = 1'b0;
        endcase

        case ({s_axi_arvalid, current_state == ACCESS})
            2'b10, 2'b11, 2'b01: is_read = 1'b1;
            default: is_read = 1'b0;
        endcase

        // State transition logic
        case (current_state)
            IDLE: begin
                case ({s_axi_awvalid, s_axi_arvalid})
                    2'b10, 2'b11: next_state = SETUP;
                    2'b01:        next_state = SETUP;
                    default:      next_state = IDLE;
                endcase
            end

            SETUP: begin
                case (m_apb_pready)
                    1'b1: next_state = ACCESS;
                    default: next_state = SETUP;
                endcase
            end

            ACCESS: begin
                case (m_apb_pready)
                    1'b1: next_state = RESPONSE;
                    default: next_state = ACCESS;
                endcase
            end

            RESPONSE: begin
                case ({is_write && s_axi_bready, is_read && s_axi_rready})
                    2'b10, 2'b11, 2'b01: next_state = IDLE;
                    default: next_state = RESPONSE;
                endcase
            end
        endcase
    end

    // Block 4: APB Control Logic
    always_comb begin
        m_apb_paddr = 32'b0;
        m_apb_psel = 1'b0;
        m_apb_penable = 1'b0;
        m_apb_pwrite = 1'b0;
        m_apb_pwdata = 32'b0;

        case (current_state)
            SETUP, ACCESS: begin
                m_apb_psel = 1'b1;
                m_apb_paddr = addr_reg;
                m_apb_pwrite = write_reg;
                m_apb_pwdata = s_axi_wdata;
                case (current_state)
                    ACCESS: m_apb_penable = 1'b1;
                    default: m_apb_penable = 1'b0;
                endcase
            end
        endcase
    end

    // Block 5: AXI Handshake Logic
    always_comb begin
        s_axi_awready = 1'b0;
        s_axi_wready  = 1'b0;
        s_axi_arready = 1'b0;
        s_axi_bvalid  = 1'b0;
        s_axi_rvalid  = 1'b0;
        s_axi_bresp   = 2'b00;
        s_axi_rresp   = 2'b00;
        s_axi_rdata   = 32'b0;

        case (current_state)
            IDLE: begin
                s_axi_awready = 1'b1;
                s_axi_wready  = 1'b1;
                s_axi_arready = 1'b1;
            end

            RESPONSE: begin
                case (is_write)
                    1'b1: begin
                        s_axi_bvalid = 1'b1;
                        case (m_apb_pslverr)
                            1'b1: s_axi_bresp = 2'b10;
                            default: s_axi_bresp = 2'b00;
                        endcase
                    end
                    1'b0: begin
                        s_axi_rvalid = 1'b1;
                        s_axi_rdata  = m_apb_prdata;
                        case (m_apb_pslverr)
                            1'b1: s_axi_rresp = 2'b10;
                            default: s_axi_rresp = 2'b00;
                        endcase
                    end
                endcase
            end
        endcase
    end

endmodule

